'use client';

import { Card } from '@/components/ui/card';

const DEMO_TRACE = [
  {
    name: 'Research Agent',
    node: 'research_trends',
    duration: '1.2s',
    detail: 'Audience angles & demand signals for ICP',
  },
  {
    name: 'Brand Agent (Voice RAG)',
    node: 'retrieve_voice_rag',
    duration: '0.8s',
    detail: 'pgvector HNSW cosine retrieval over creator docs',
  },
  {
    name: 'Writer Agent',
    node: 'draft_post',
    duration: '2.1s',
    detail: 'Hook + body + CTA synthesis via Groq',
  },
  {
    name: 'Reviewer Agent',
    node: 'critique_and_score',
    duration: '0.7s',
    detail: 'Virality / scroll-stop / brand alignment score',
  },
];

export default function TracesPage() {
  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold md:text-4xl">Agent Traces</h1>
        <p className="mt-2 text-slate-400">
          LangGraph node timeline for the LinkedIn strategist pipeline. Live runs
          surface duration and summaries from the API response.
        </p>
      </div>

      <Card>
        <div className="space-y-4">
          {DEMO_TRACE.map((step, i) => (
            <div
              key={step.node}
              className="flex flex-col gap-1 rounded-xl bg-white/5 p-4 sm:flex-row sm:items-center sm:justify-between"
            >
              <div>
                <p className="font-medium text-white">
                  <span className="mr-2 text-slate-500">
                    {String(i + 1).padStart(2, '0')}.
                  </span>
                  {step.name}
                </p>
                <p className="text-xs text-slate-500 font-mono">{step.node}</p>
                <p className="mt-1 text-sm text-slate-400">{step.detail}</p>
              </div>
              <span className="shrink-0 text-green-400">✅ {step.duration}</span>
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <h2 className="mb-2 text-lg font-semibold">Observability</h2>
        <p className="text-sm text-slate-400">
          When Langfuse credentials are set on the backend, each{' '}
          <code className="rounded bg-white/10 px-1.5 py-0.5 text-xs">
            /strategist/generate
          </code>{' '}
          call emits a trace with node-level spans. Check the FastAPI response field{' '}
          <code className="rounded bg-white/10 px-1.5 py-0.5 text-xs">
            langfuseTraceId
          </code>
          .
        </p>
      </Card>
    </div>
  );
}